<?php require_once __DIR__.'/includes/functions.php';$order=null;if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$st=db()->prepare('SELECT * FROM orders WHERE order_number=? AND phone=?');$st->execute([$_POST['order_number'],$_POST['phone']]);$order=$st->fetch();if(!$order)flash('error','لم نعثر على طلب بهذه البيانات.');}$title='تتبّع الطلب | ALAN';include __DIR__.'/includes/header.php';?><div class="page"><div class="tracking"><div class="page-title"><p class="eyebrow">طلباتكِ</p><h1>تتبّع طلبكِ</h1></div><form class="form-card" method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><label>رقم الطلب</label><input name="order_number" required placeholder="ALN-2026-0001"><label>رقم الهاتف</label><input name="phone" required placeholder="0550 000 000"><button class="btn" style="margin-top:15px">عرض الحالة</button></form><?php if($order):$statuses=['received'=>'تم استلام الطلب','confirmed'=>'تم تأكيد الطلب','preparing'=>'جاري التحضير','shipped'=>'تم الشحن','out_for_delivery'=>'في طريقه إليكِ','delivered'=>'تم التسليم'];$keys=array_keys($statuses);$current=array_search($order['status'],$keys);?><div class="timeline"><?php foreach($statuses as $k=>$v):?><div class="<?=$current<array_search($k,$keys)?'muted':''?>"><strong><?=$v?></strong><br><small><?=$k===$order['status']?'آخر تحديث: '.e($order['updated_at']):''?></small></div><?php endforeach;?></div><?php endif;?></div></div><?php include __DIR__.'/includes/footer.php';?>
